import sys, types
GLOBAL_X = 42

def via_listcomp(items):       # mirrors remove_bufferize: listcomp INSIDE lambda
  return list(map(lambda i: [GLOBAL_X for _ in range(i)], items))
def via_genexp(items):         # genexp INSIDE lambda
  return list(map(lambda i: list(GLOBAL_X for _ in range(i)), items))
def via_direct_comp(items):    # listcomp directly in function body (depth 1)
  return [GLOBAL_X for _ in items]

def harvest(fxn):              # exact mirror of ops.py:1332-1334
  ng = {k: v for k, v in fxn.__globals__.items() if k in fxn.__code__.co_names}
  for co in fxn.__code__.co_consts:
    if isinstance(co, types.CodeType):
      ng.update({k: v for k, v in fxn.__globals__.items() if k in co.co_names})
  return ng

def dump(code, d=0):
  kids = [c for c in code.co_consts if isinstance(c, types.CodeType)]
  print("  " * d + f"depth{d} {code.co_name!r}: co_names={code.co_names} co_varnames={code.co_varnames}")
  for c in kids: dump(c, d + 1)

print("python", sys.version.split()[0])
for fn in (via_listcomp, via_genexp, via_direct_comp):
