  dump(fn.__code__)
  h = harvest(fn)
  print("   harvest got GLOBAL_X:", "GLOBAL_X" in h)
  rebuilt = types.FunctionType(fn.__code__, h, fn.__name__, fn.__defaults__)
  try:
    rebuilt([2]); print("   rebuilt call: ok")
  except NameError as e:
    print("   rebuilt call: NameError:", e)
